/* Prism's chat: playful and soft. A prompt bubble tinted in the accent with 16 px corners and no
   edge, cards tinted faintly in the space color (the accent) with an accent hairline, secondary
   text as quiet as it can be while it stays readable, and links in the accent a step toward the
   text.
   Only cmux.agentPane.style/1 tokens (schemas/agent-pane/style-tokens.json), on :root: paint, so
   nothing in the transcript moves when this applies or reloads. Every color is made from the
   theme's own (--agent-text, --agent-accent, --agent-page-bg), so it reads over Prism and Prism
   Dark and over any theme of your own. */
:root {
  --cv-user-bubble-tint: color-mix(in srgb, var(--agent-accent) 14%, transparent);
  --cv-user-bubble-edge: transparent;
  --cv-user-bubble-radius: 16px;
  --cv-card-fill: color-mix(in srgb, var(--agent-accent) 5%, transparent);
  --cv-card-ring: color-mix(in srgb, var(--agent-accent) 16%, transparent);
  --cv-text-muted: color-mix(in srgb, var(--agent-text) 72%, transparent);
  --cv-text-dim: color-mix(in srgb, var(--agent-text) 64%, transparent);
  --cv-link: color-mix(in srgb, var(--agent-accent) 85%, var(--agent-text));
  --agent-link: color-mix(in srgb, var(--agent-accent) 85%, var(--agent-text));

  /* Pending cmux#46846 (--menu-*): menus and popovers. Inert until it lands.
     Measured from the source menus at 2x: a panel tinted by the space color (the page with 8% of
     the accent), 10 px corners, a 5 px inset, 24 px rows, the highlighted row an inset 6 px
     capsule of the accent, shortcuts in the secondary text at the right, semibold section
     labels, separators inset 11 px, destructive rows in the theme's red (the default), and
     submenus that overlap their menu by the inset so their first row meets the row that opened
     them. */
  --menu-radius: 10px;
  --menu-padding: 5px;
  --menu-fill: color-mix(in srgb, var(--agent-accent) 8%, var(--agent-page-bg));
  --menu-border: color-mix(in srgb, var(--agent-text) 12%, transparent);
  --menu-row-height: 24px;
  --menu-hover-fill: color-mix(in srgb, var(--agent-accent) 26%, transparent);
  --menu-hover-radius: 6px;
  --menu-separator: color-mix(in srgb, var(--agent-text) 12%, transparent);
  --menu-separator-inset: 11px;
  --menu-label-color: color-mix(in srgb, var(--agent-text) 70%, transparent);
  --menu-label-weight: 600;
  --menu-label-size: var(--text-caption);
  --menu-shortcut-color: color-mix(in srgb, var(--agent-text) 70%, transparent);
  --menu-subtitle-color: color-mix(in srgb, var(--agent-text) 70%, transparent);
  --menu-disabled-opacity: 0.4;
  --menu-submenu-offset: -5px;
  --menu-submenu-align-offset: -5px;
}

